// n8n Code node «Build AI Request» — Run Once for All Items.
// Вхід: items з «Get Inputs» (рядки листа Inputs цієї пачки) АБО, на кроці review, одне нове повідомлення.
// Вихід: { body } — готове тіло для HTTP Request до OpenAI (поле JSON = {{ $json.body }}), плюс службові поля.
// Чому тіло збираємо в коді: так ніякі лапки й переноси в документах не ламають JSON (урок про ={{ }}).

const cfg = $('Template Config').first().json;
const session = $('Get Session').first().json;
const role = session.role || '';
const coKey = role.startsWith('uts') ? 'uts' : 'automov';
const co = cfg.OUR[coKey];
const side = role.endsWith('_z') ? 'z' : role.endsWith('_p') ? 'p' : 'both';
const mode = session.step === 'review' ? 'patch' : 'extract';

const MAX = 300000;
let bundle = '', count = 0, cut = false;
let sides = false;
if (mode === 'extract') {
  // kind = «pdf» або «pdf:client» / «pdf:carrier» — сторону менеджер задає кнопкою «🚚 Далі: перевізник» (режим «Обидва»)
  const rows = $input.all().map(it => it.json)
    .filter(r => String(r.batch_id) === String(session.batch_id) && String(r.text || '').trim());
  const sideOf = r => String(r.kind || '').split(':')[1] || '';
  sides = rows.some(r => sideOf(r));
  const groups = sides
    ? [['client', '##### ДОКУМЕНТИ ЗАМОВНИКА #####'], ['carrier', '##### ДОКУМЕНТИ ПЕРЕВІЗНИКА #####'], ['', '##### ІНШЕ #####']]
    : [['', '']];
  outer: for (const [g, title] of groups) {
    const part = rows.filter(r => (sides ? sideOf(r) === g : true));
    if (!part.length) continue;
    if (title) bundle += title + '\n\n';
    for (const r of part) {
      count++;
      const block = `=== Документ ${count} (${String(r.kind).split(':')[0]}${r.name ? ': ' + r.name : ''}) ===\n${String(r.text).trim()}\n\n`;
      if (bundle.length + block.length > MAX) { cut = true; break outer; }
      bundle += block;
    }
  }
} else {
  bundle = String($('Normalize Text').first().json.userText || '').trim();
  count = 1;
}

let current = {};
try { current = JSON.parse(session.data || '{}'); } catch (e) { current = {}; }

const keys = Object.keys(cfg.FIELDS);
const sideRule = {
  z: 'Тип договору: з ЗАМОВНИКОМ. Усі сторонні компанії за замовчуванням — замовник (CLIENT_*). CARRIER_* заповнюй лише якщо в тексті явно сказано «перевізник».',
  p: 'Тип договору: заявка ПЕРЕВІЗНИКУ. Усі сторонні компанії за замовчуванням — перевізник (CARRIER_*). CLIENT_* заповнюй лише якщо в тексті явно сказано «замовник».',
  both: 'Тип: ОБИДВА договори. Визнач сторону кожної компанії за мітками «Замовник/Перевізник» і за змістом: хто платить за перевезення — замовник; чиє авто, водій, техпаспорт, посвідчення — перевізник. Якщо сторону визначити не можна — НЕ вгадуй, додай компанію в unassigned.',
}[side] + (sides
  ? '\nДокументи РОЗДІЛЕНІ менеджером заголовками «ДОКУМЕНТИ ЗАМОВНИКА» / «ДОКУМЕНТИ ПЕРЕВІЗНИКА» — це точний поділ: компанія з розділу замовника → CLIENT_*, з розділу перевізника → CARRIER_*. Явні мітки в тексті («Перевізник: …», «Замовник: …») мають пріоритет. Ціни, маршрут, вантаж, авто й водій можуть бути в будь-якому розділі.'
  : '');

const system = [
  'Ти — асистент логіста в Україні. Із документів (виписки, реквізити, заявки, фото техпаспорта й посвідчення, голосові) заповни поля договору.',
  `ЕКСПЕДИТОР — це ми: ${co.text}. НІКОЛИ не записуй експедитора в CLIENT_* чи CARRIER_*. Менеджер експедитора: ${cfg.MANAGER} — це EXPEDITOR_CONTACT, не контакт сторін.`,
  sideRule,
  'Правила: назви повністю великими як у виписці («ТОВАРИСТВО З ОБМЕЖЕНОЮ ВІДПОВІДАЛЬНІСТЮ «…»», «ФІЗИЧНА ОСОБА-ПІДПРИЄМЕЦЬ …»). ПІБ — повністю. ЄДРПОУ — 8 цифр, у ФОП РНОКПП — 10 цифр. IBAN — повністю, як у документі: «UA» і 27 цифр (перші 2 цифри після UA — контрольні, їх НЕ пропускай), без пробілів. Цифри переписуй точно, нічого не округлюй.',
  'ФОП не має директора й статуту: *_DIRECTOR = ПІБ самого ФОП, *_BASIS = «Виписки з ЄДР». ТОВ: *_BASIS = «Статуту», якщо не сказано інше.',
  'CONTRACT_NUMBER — номер угоди в CRM, якщо його названо (лише цифри). Це і є номер договору.',
  'CARRIER_TAX — податковий статус перевізника, напр. «Платник єдиного податку 3 групи (5%)» або «Платник ПДВ». Обовʼязково вкажи, чи є реєстрація ПДВ: «…, платник ПДВ» або «…, без ПДВ». Якщо серед документів перевізника є «Витяг з реєстру платників податку на додану вартість» або написано «із реєстрацією ПДВ» — він платник ПДВ.',
  'ROUTE у форматі «м. Київ - м. Львів» (префікси м., с., смт). Ціни (SERVICE_PRICE, TRANSPORT_PRICE, CARGO_VALUE) — лише цифри в грн. Дати — ДД.ММ.РРРР, час якщо є.',
  'Рейс внутрішній → CUSTOMS_LOADING, BORDER_POINT, CUSTOMS_UNLOADING = порожні.',
  'Якщо одне поле має РІЗНІ значення в різних документах — у поле запиши найнадійніше (виписка > реквізити > рахунок > фото), а всі варіанти додай у conflicts.',
  'SERVICE_PRICE — ціна для замовника, TRANSPORT_PRICE — плата перевізнику. Якщо названо одну ціну без уточнення: у договорі з замовником це SERVICE_PRICE, у заявці перевізнику — TRANSPORT_PRICE. Не дублюй одну ціну в обидва поля.',
  'Умови й строки оплати НЕ записуй нікуди (порядок оплати вже надрукований у шаблоні). EXTRA_CONDITIONS — лише якщо користувач прямо каже «додаткові умови»; інакше порожньо.',
  'Поле не знайдено — порожній рядок. Не вигадуй. notes — лише важливе, чого НЕМАЄ в полях (не повторюй знайдені дані), до 200 символів; якщо такого немає — порожньо.',
  mode === 'patch'
    ? 'РЕЖИМ ВИПРАВЛЕННЯ. Тобі дано поточні дані (JSON) і нове повідомлення користувача. Зміни ЛИШЕ те, що просить або додає повідомлення; решту поверни без змін. conflicts і unassigned — порожні, якщо повідомлення їх не стосується.'
    : '',
].filter(Boolean).join('\n');

const user = mode === 'patch'
  ? `ПОТОЧНІ ДАНІ:\n${JSON.stringify(current)}\n\nНОВЕ ПОВІДОМЛЕННЯ:\n${bundle}`
  : bundle;

const props = {};
keys.forEach(k => { props[k] = { type: 'string' }; });
props.conflicts = { type: 'array', items: { type: 'object', additionalProperties: false, required: ['field', 'options'],
  properties: { field: { type: 'string' }, options: { type: 'array', items: { type: 'string' } } } } };
props.unassigned = { type: 'array', items: { type: 'object', additionalProperties: false, required: ['name', 'edrpou'],
  properties: { name: { type: 'string' }, edrpou: { type: 'string' } } } };
props.notes = { type: 'string' };

const body = {
  model: 'gpt-4.1-mini',
  temperature: 0,
  messages: [{ role: 'system', content: system }, { role: 'user', content: user }],
  response_format: { type: 'json_schema', json_schema: { name: 'contract_data', strict: true,
    schema: { type: 'object', additionalProperties: false, required: Object.keys(props), properties: props } } },
};

return [{ json: { body, mode, count, cut, chars: bundle.length, empty: !bundle } }];

// n8n Code node «Post-process» — Run Once for All Items. Без ШІ: усе детерміновано.
// Вхід: відповідь HTTP Request «OpenAI Extract» (chat/completions).
// Вихід: { data, dataJson, missing, warnings, conflicts, unassigned, notes, docs } — далі в «Save Session» і «Review Screen».

const cfg = $('Template Config').first().json;
const session = $('Get Session').first().json;
const role = session.role || '';
const coKey = role.startsWith('uts') ? 'uts' : 'automov';
const co = cfg.OUR[coKey];

// --- відповідь моделі ---
const resp = $input.first().json;
let out = {};
try { out = JSON.parse(resp.choices[0].message.content); }
catch (e) { return [{ json: { error: 'Не вдалося прочитати відповідь ШІ. Спробуйте ще раз.' } }]; }

let prev = {};
try { prev = JSON.parse(session.data || '{}'); } catch (e) { prev = {}; }

const data = {};
for (const k of Object.keys(cfg.FIELDS)) {
  const v = String(out[k] ?? '').replace(/\s+/g, ' ').trim();
  data[k] = v || String(prev[k] || '');   // нове порожнє не стирає вже відоме
}

// --- перевірки кодів ---
function edrpouOk(s) {
  if (!/^\d{8}$/.test(s)) return false;
  const d = [...s].map(Number), n = +s;
  const w1 = (n < 30000000 || n > 60000000) ? [1, 2, 3, 4, 5, 6, 7] : [7, 1, 2, 3, 4, 5, 6];
  let c = w1.reduce((a, w, i) => a + w * d[i], 0) % 11;
  if (c >= 10) { const w2 = w1.map(w => w + 2); c = w2.reduce((a, w, i) => a + w * d[i], 0) % 11; if (c >= 10) c = 0; }
  return c === d[7];
}
function rnokppOk(s) {
  if (!/^\d{10}$/.test(s)) return false;
  const d = [...s].map(Number), w = [-1, 5, 7, 9, 4, 6, 10, 5, 7];
  return (w.reduce((a, x, i) => a + x * d[i], 0) % 11) % 10 === d[9];
}
function ibanNorm(s) { s = String(s || '').replace(/\s/g, '').toUpperCase(); if (/^\d{27}$/.test(s)) s = 'UA' + s; return s; }
function ibanOk(s) {
  s = ibanNorm(s); if (!/^UA\d{27}$/.test(s)) return false;
  const r = (s.slice(4) + s.slice(0, 4)).replace(/[A-Z]/g, c => c.charCodeAt(0) - 55);
  let m = 0; for (const ch of r) m = (m * 10 + +ch) % 97; return m === 1;
}
const codeOk = v => (v.length === 8 ? edrpouOk(v) : v.length === 10 ? rnokppOk(v) : false);

// IBAN-и, що є в тексті документів і проходять контрольну суму — для виправлення помилки ШІ (загублена/зайва цифра)
let src = '';
try { src = String($('Build AI Request').first().json.body.messages[1].content || ''); } catch (e) { src = ''; }
const srcIbans = [...new Set([...src.matchAll(/UA[\d \t]{27,45}/gi)]
  .map(m => m[0].replace(/\s/g, '').toUpperCase().slice(0, 29)).filter(ibanOk))]
  .filter(ib => !String(co.text || '').replace(/\s/g, '').includes(ib));
function lev(a, b) {
  const d = Array.from({ length: a.length + 1 }, (_, i) => [i]);
  for (let j = 1; j <= b.length; j++) d[0][j] = j;
  for (let i = 1; i <= a.length; i++) for (let j = 1; j <= b.length; j++)
    d[i][j] = Math.min(d[i - 1][j] + 1, d[i][j - 1] + 1, d[i - 1][j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
  return d[a.length][b.length];
}

const warnings = [];
for (const p of ['CLIENT', 'CARRIER']) {
  const who = p === 'CLIENT' ? 'замовника' : 'перевізника';
  const code = data[p + '_EDRPOU'].replace(/\D/g, '');
  if (data[p + '_EDRPOU']) { data[p + '_EDRPOU'] = code; if (!codeOk(code)) warnings.push(`Код ${who} ${code} не проходить перевірку — перевірте цифри`); }
  if (data[p + '_IBAN']) {
    let ib = ibanNorm(data[p + '_IBAN']);
    if (!ibanOk(ib)) {
      // у тексті документа є правильний IBAN, що відрізняється на 1–3 символи → це він, ШІ помилився при переписуванні
      const near = srcIbans.filter(c => lev(c, ib.startsWith('UA') ? ib : 'UA' + ib) <= 3);
      if (near.length === 1) ib = near[0];
    }
    // у шаблонах IBAN без UA (як у v1)
    data[p + '_IBAN'] = ib.replace(/^UA/, '');
    if (!ibanOk(ib)) warnings.push(`IBAN ${who} не проходить контрольну суму — найчастіше одна цифра розпізнана неправильно`);
  }
  const name = data[p + '_COMPANY'];
  if (/ФІЗИЧНА ОСОБА|^ФОП/i.test(name)) {
    if (/статут/i.test(data[p + '_BASIS'])) data[p + '_BASIS'] = 'Виписки з ЄДР';
    if (!data[p + '_DIRECTOR']) data[p + '_DIRECTOR'] = name.replace(/ФІЗИЧНА ОСОБА\s*-\s*ПІДПРИЄМЕЦЬ|ФОП/i, '').trim();
    if (!data[p + '_IPN'] && code.length === 10) data[p + '_IPN'] = code;
  } else if (name && (!data[p + '_BASIS'] || /ЄДР|відомост|виписк/i.test(data[p + '_BASIS']))) {
    data[p + '_BASIS'] = 'Статуту';   // ТОВ/ПП — на підставі Статуту, якщо не сказано інше (довіреність тощо)
  }
  // експедитора не пускаємо в сторони
  if (code === co.edrpou) { warnings.push(`У ${who} потрапили наші реквізити (${co.short}) — поля ${who} очищено`);
    Object.keys(data).filter(k => k.startsWith(p + '_')).forEach(k => { data[k] = ''; }); }
}

// --- ПІБ: «ПЕТРЕНКО ОЛЕНА ІВАНІВНА» → «Петренко Олена Іванівна» (лише якщо все великими) ---
// межа слова — пробіл або дефіс; після апострофа велику не ставимо («Дем'яненко»)
const nameCase = s => (/[a-zа-яіїєґ]/.test(s) ? s : s.toLowerCase().replace(/(^|[\s-])([a-zа-яіїєґ])/g, (m, a, b) => a + b.toUpperCase()));
data.CLIENT_DIRECTOR = nameCase(data.CLIENT_DIRECTOR);
data.CARRIER_DIRECTOR = nameCase(data.CARRIER_DIRECTOR);

// --- короткі форми (одна функція замість трьох копій v1) ---
const shortCo = s => s.replace('ТОВАРИСТВО З ОБМЕЖЕНОЮ ВІДПОВІДАЛЬНІСТЮ', 'ТОВ').replace(/ФІЗИЧНА ОСОБА\s*-\s*ПІДПРИЄМЕЦЬ/i, 'ФОП').replace('ПРИВАТНЕ ПІДПРИЄМСТВО', 'ПП').trim();
const shortName = s => { const p = s.trim().split(/\s+/); return p.length >= 3 ? `${p[0]} ${p[1][0]}.${p[2][0]}.` : s; };
data.CLIENT_COMPANY_SHORT = shortCo(data.CLIENT_COMPANY);
data.CLIENT_DIRECTOR_SHORT = shortName(data.CLIENT_DIRECTOR);
data.CARRIER_COMPANY_SHORT = shortCo(data.CARRIER_COMPANY);
data.CARRIER_DIRECTOR_SHORT = shortName(data.CARRIER_DIRECTOR);

// --- гроші ---
for (const k of ['SERVICE_PRICE', 'TRANSPORT_PRICE', 'CARGO_VALUE']) data[k] = data[k].replace(/[^\d.,]/g, '').replace(',', '.').replace(/\.0+$/, '');
// одна й та сама ціна в обох полях = модель продублювала одну названу ціну; лишаємо її лише в полі цього договору
if (data.SERVICE_PRICE && data.SERVICE_PRICE === data.TRANSPORT_PRICE) {
  if (role.endsWith('_z')) data.TRANSPORT_PRICE = '';
  else if (role.endsWith('_p')) data.SERVICE_PRICE = '';
}
const z = +data.SERVICE_PRICE || 0, p = +data.TRANSPORT_PRICE || 0;
if (z && p) {
  const net = co.vat ? z / 1.2 : z;
  const m = (net - p) / net * 100;
  if (m < 0) warnings.push(`Збиток: перевізнику ${p} грн більше, ніж отримуємо від замовника`);
  else if (m < 8) warnings.push(`Маржа лише ${m.toFixed(1)}% (типова — 13%)`);
}

// --- міжнародний рейс ---
const intl = !!(data.CUSTOMS_LOADING || data.BORDER_POINT || data.CUSTOMS_UNLOADING);
if (intl && !co.intl) warnings.push(`${co.short} оформлює лише внутрішні перевезення — для міжнародного рейсу оберіть АвтоМув`);

// --- службові ---
const now = new Date(Date.now() + 2 * 3600e3); // Київ (без літнього часу — для дати договору достатньо)
const dd = n => String(n).padStart(2, '0');
data.CONTRACT_DATE = `${dd(now.getUTCDate())}.${dd(now.getUTCMonth() + 1)}.${now.getUTCFullYear()}`;
data.CONTRACT_NUMBER = data.CONTRACT_NUMBER.replace(/\D/g, '');  // № угоди в CRM = № договору
data.TRANSPORT_TYPE = 'Вантажоперевезення';
data.EXPEDITOR_CONTACT = data.EXPEDITOR_CONTACT || cfg.MANAGER;

// --- чого бракує по кожному шаблону ---
const docs = (cfg.ROLE_DOCS[role] || []).map(id => {
  const t = cfg.TEMPLATES[id];
  const req = [...t.required, ...(intl ? cfg.INTL_REQ : [])];
  const miss = req.filter(k => !data[k]);
  if (!data.CONTRACT_NUMBER) miss.unshift('CONTRACT_NUMBER');
  return { id, title: t.title, side: t.side, missing: miss };
});
const missing = [...new Set(docs.flatMap(d => d.missing))];

const conflicts = (out.conflicts || []).filter(c => c.options && new Set(c.options).size > 1);
const unassigned = out.unassigned || [];

return [{ json: {
  data, dataJson: JSON.stringify(data), docs, missing, warnings, conflicts, unassigned,
  notes: String(out.notes || '').trim(), intl,
} }];

// n8n Code node «Review Screen» — Run Once for All Items.
// Вхід: вихід «Post-process». Вихід: { text } для Telegram «Send Review» (без parse mode, з inline-кнопками
// «🚀 Генерувати» = callback gen і «❌ Скасувати» = callback cancel — вони статичні, налаштовуються в самому вузлі).
// Конфлікти й «чия це компанія» не мають окремих кнопок: користувач відповідає голосом/текстом, це йде в Patch.

const cfg = $('Template Config').first().json;
const r = $('Post-process').first().json;
if (r.error) return [{ json: { text: '⚠️ ' + r.error } }];

const d = r.data, F = cfg.FIELDS;
const session = $('Get Session').first().json;
const cut = (s, n = 70) => (s.length > n ? s.slice(0, n - 1) + '…' : s);
const show = (k, label) => d[k] ? `${label || F[k]}: ${cut(d[k])}` : null;
const tail = s => (s ? '…' + s.slice(-4) : '');

const coKey = (session.role || '').startsWith('uts') ? 'uts' : 'automov';
const roleTxt = { z: 'договір із замовником', p: 'заявка перевізнику' };
const docsTxt = r.docs.map(x => roleTxt[x.side]).join(' + ');
const req = new Set(r.docs.flatMap(x => cfg.TEMPLATES[x.id].required));
const found = [...req].filter(k => d[k]).length;

const L = [];
L.push(`📋 ${cfg.OUR[coKey].short} → ${docsTxt}`);
L.push(d.CONTRACT_NUMBER
  ? `№ угоди: ${d.CONTRACT_NUMBER}  ·  знайдено ${found} з ${req.size}`
  : `⚠️⚠️ № УГОДИ НЕ ВКАЗАНО — напишіть «угода 62811450»
Знайдено ${found} з ${req.size}`);

const sides = r.docs.map(x => x.side);
if (sides.includes('z')) {
  L.push('', 'ЗАМОВНИК');
  [show('CLIENT_COMPANY_SHORT', 'Назва'), d.CLIENT_EDRPOU && `ЄДРПОУ: ${d.CLIENT_EDRPOU}   IBAN: ${tail(d.CLIENT_IBAN)}`,
    show('CLIENT_DIRECTOR', 'Директор'), show('CLIENT_PHONE', 'Телефон')].filter(Boolean).forEach(x => L.push(x));
}
L.push('', 'РЕЙС');
[show('ROUTE'), show('CARGO_INFO'),
  (d.LOADING_DATE || d.LOADING_ADDRESS) && `Завантаження: ${cut([d.LOADING_DATE, d.LOADING_ADDRESS].filter(Boolean).join(', '))}`,
  (d.DELIVERY_DATE || d.UNLOADING_ADDRESS) && `Доставка: ${cut([d.DELIVERY_DATE, d.UNLOADING_ADDRESS].filter(Boolean).join(', '))}`,
  show('VEHICLE_INFO', 'Авто'), show('DRIVER_INFO', 'Водій')].filter(Boolean).forEach(x => L.push(x));
if (sides.includes('p')) {
  L.push('', 'ПЕРЕВІЗНИК');
  [show('CARRIER_COMPANY_SHORT', 'Назва'), d.CARRIER_EDRPOU && `Код: ${d.CARRIER_EDRPOU}   IBAN: ${tail(d.CARRIER_IBAN)}`,
    show('CARRIER_TAX', 'Податки'), show('CARRIER_PHONE', 'Телефон')].filter(Boolean).forEach(x => L.push(x));
}
const money = n => Number(n).toLocaleString('uk-UA') + ' грн';
const z = +d.SERVICE_PRICE || 0, p = +d.TRANSPORT_PRICE || 0;
if (z || p) {
  L.push('', 'ГРОШІ');
  if (z) L.push(`Замовник: ${money(z)}${d.CLIENT_TERMS ? ', ' + cut(d.CLIENT_TERMS, 50) : ''}`);
  if (p) L.push(`Перевізник: ${money(p)}${d.CARRIER_TERMS ? ', ' + cut(d.CARRIER_TERMS, 50) : ''}`);
  if (z && p) L.push(`Маржа: ${money(z - p)}`);
}

if (r.missing.length) L.push('', '❗ Не знайдено: ' + r.missing.map(k => F[k] || k).join(', '));
r.conflicts.forEach(c => L.push(`⚠️ ${F[c.field] || c.field}: різні значення — ${c.options.map(o => cut(o, 45)).join(' / ')}. Скажіть, яке правильне.`));
r.unassigned.forEach(u => L.push(`❓ ${cut(u.name, 50)}${u.edrpou ? ' (' + u.edrpou + ')' : ''} — це замовник чи перевізник?`));
r.warnings.forEach(w => L.push('⚠️ ' + w));
if (r.notes) L.push('ℹ️ ' + cut(r.notes, 300));

L.push('', r.missing.length
  ? 'Надішліть голосом або текстом, що додати чи змінити. Можна також фото або файл.'
  : 'Усе на місці. Натисніть «🚀 Генерувати» або надішліть, що змінити.');

let text = L.join('\n');
if (text.length > 4000) text = text.slice(0, 3990) + '\n…';
return [{ json: { text, canGenerate: r.missing.length === 0 } }];

const binaryBuffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const base64String = binaryBuffer.toString('base64');
const fileName = $('Telegram Trigger').first().json.message.document.file_name || 'document.pdf';

return [{json: {pdfBase64: base64String, fileName}, binary: $input.first().binary}];

